.button {
  color: #efe0f1;
  font-size: 17px;
  background-color: #e67e22;
  border: 1px solid #f39c12;
  border-radius: 5px;
  cursor: pointer;
  padding: 10px;
  box-shadow: 0px 6px 0px #d35400;
  transition: all 0.1s;
}

.button:active {
  box-shadow: 0px 2px 0px #d35400;
  position: relative;
  top: 2px;
}

.bauble_box .bauble_label {
  background: #2c2;
  background-position: 62px 5px;
  background-repeat: no-repeat;
  background-size: auto 5px;
  border: 0;
  border-radius: 50px;
  box-shadow: inset 0 10px 20px rgba(0,0,0,.4), 0 -1px 0 rgba(0,0,0,.2), inset 0 -1px 0 #fff;
  cursor: pointer;
  display: inline-block;
  font-size: 0;
  height: 40px;
  position: relative;
  transition: all 500ms ease;
  width: 90px;
}
.bauble_box .bauble_label:before {
  background-color: rgba(255,255,255,.2);
  border-radius: 50%;
  box-shadow: inset 0 -5px 25px #050, 0 10px 20px rgba(0,0,0,.4);
  content: '';
  display: block;
  height: 30px;
  left: 5px;
  position: absolute;
  top: 6px;
  transition: all 500ms ease;
  width: 30px;
  z-index: 2;
}
.bauble_box input.bauble_input {
  opacity: 0;
  position: absolute;
  z-index: 0;
}
.bauble_box input.bauble_input:checked + .bauble_label {
  background-color: #c22;
}
.bauble_box input.bauble_input:checked + .bauble_label:before {
  box-shadow: inset 0 -5px 25px #500, 0 10px 20px rgba(0,0,0,.4);
  left: calc(100% - 35px);
}

.container {
  position: relative;
  width: 70px;
  height: 58px;
}
.label-check {
  display: none;
}
.hamburger-label {
  width: 70px;
  height: 58px;
  display: block;
  cursor: pointer;
  position: relative;
}
.hamburger-label div {
  width: 70px;
  height: 6px;
  background-color: #fff;
  position: absolute;
  left: 0;
}
.line1 { top: 0; transition: all .3s; }
.line2 { top: 18px; transition: .3s; }
.line3 { top: 36px; transition: .3s; }
#label-check:checked + .hamburger-label .line1 {
  transform: rotate(35deg) scaleX(.55) translate(39px, -4.5px);
  border-radius: 50px 50px 50px 0;
}
#label-check:checked + .hamburger-label .line3 {
  transform: rotate(-35deg) scaleX(.55) translate(39px, 4.5px);
  border-radius: 0 50px 50px 50px;
}
#label-check:checked + .hamburger-label .line2 {
  border-top-right-radius: 50px;
  border-bottom-right-radius: 50px;
  width: 45px;
}

.switch {
  --secondary-container: #3a4b39;
  --primary: #84da89;
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.7em;
  height: 1.8em;
}
.switch input {
  display: none;
  opacity: 0;
  width: 0;
  height: 0;
}
.slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background-color: #313033;
  transition: .2s;
  border-radius: 30px;
}
.slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 20px;
  left: 0.2em;
  bottom: 0.2em;
  background-color: #aeaaae;
  transition: .4s;
}
input:checked + .slider::before {
  background-color: var(--primary);
}
input:checked + .slider {
  background-color: var(--secondary-container);
}
input:focus + .slider {
  box-shadow: 0 0 1px var(--secondary-container);
}
input:checked + .slider:before {
  transform: translateX(1.9em);
}

.liquid-3 {
  --primary: #000;
  --secondary: #fff;
  --time: 0.6s;
  appearance: none;
  position: relative;
  cursor: pointer;
  width: 10em;
  aspect-ratio: 2 / 1;
  background: var(--primary);
  border-radius: 20em;
  box-shadow: 0 0 0 1em var(--secondary);
  transform: translateX(0.5px);
  transition: transform var(--time) cubic-bezier(0.75, 0, 0.75, 50);
  filter: blur(0.66em) contrast(20);
  mix-blend-mode: darken;
  overflow: hidden;
}
.liquid-3::before {
  content: "";
  position: absolute;
  width: 200%;
  height: 100%;
  transform: translate(-25%, -50%);
  left: 50%;
  top: 50%;
  background:
    radial-gradient(closest-side circle at 12.5% 50%, var(--secondary) 50%, #0000 0),
    radial-gradient(closest-side circle at 87.5% 50%, var(--secondary) 50%, #0000 0),
    #f000;
  transition: transform var(--time) cubic-bezier(0.75, 0, 0.75, 1.3);
}
.liquid-3:checked {
  transform: translateX(-0.5px);
}
.liquid-3:checked::before {
  transform: translate(-75%, -50%);
}

.switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}
.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  border: 2px solid #414141;
  border-radius: 50px;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  left: 0.2em;
  bottom: 0.2em;
  background-color: white;
  border-radius: inherit;
  transition: all 0.4s cubic-bezier(0.23, 1, 0.320, 1);
}
.switch input:checked + .slider {
  box-shadow: 0 0 20px rgba(9, 117, 241, 0.8);
  border: 2px solid #0974f1;
}
.switch input:checked + .slider:before {
  transform: translateX(1.5em);
}

/* --- MAIN SWITCH CONTAINER --- */
.switch-food {
--w: 120px;
--h: 60px;
--knob-size: 50px;
--offset: 5px;
--bg-burger: #ffecd2;
--bg-fries: #fff5e6;

position: relative;
display: inline-block;
width: var(--w);
height: var(--h);
cursor: pointer;
}

.switch-input {
opacity: 0;
width: 0;
height: 0;
}

/* The Background Track */
.switch-track {
position: absolute;
inset: 0;
background-color: var(--bg-burger);
border: 3px solid #333;
border-radius: 60px;
transition: background-color 0.4s;
overflow: hidden;
}

/* The Moving Knob Wrapper */
.switch-knob {
position: absolute;
top: var(--offset);
left: var(--offset);
width: var(--knob-size);
height: var(--knob-size);
transition: transform 0.5s cubic-bezier(0.6, -0.28, 0.735, 0.045);
display: flex;
align-items: center;
justify-content: center;
}

/* ===========================
1. THE BURGER (2D DOODLE)
=========================== */
.burger-container {
position: absolute;
width: 40px;
height: 40px;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
transition:
transform 0.4s ease,
opacity 0.3s ease;
z-index: 2;
}

.bun-top {
width: 36px;
height: 16px;
background: #ffa64d;
border: 2px solid #333;
border-bottom: none;
border-radius: 20px 20px 0 0;
position: relative;
z-index: 4;
}
.seeds {
position: absolute;
width: 2px;
height: 2px;
background: #333;
top: 6px;
left: 10px;
box-shadow:
12px 0 #333,
6px 4px #333;
border-radius: 50%;
}
.lettuce {
width: 40px;
height: 6px;
background: #8cd65e;
border: 2px solid #333;
border-radius: 10px;
margin-top: -2px;
z-index: 3;
}
.patty {
width: 36px;
height: 8px;
background: #8b4513;
border: 2px solid #333;
border-radius: 4px;
margin-top: -2px;
z-index: 2;
}
.bun-bottom {
width: 36px;
height: 10px;
background: #ffa64d;
border: 2px solid #333;
border-radius: 0 0 10px 10px;
margin-top: -2px;
z-index: 1;
}

/* ===========================
2. THE FRIES (3D)
=========================== */
.fries-container {
position: absolute;
width: 40px;
height: 40px;
perspective: 600px;
opacity: 0;
transform: scale(0);
transition:
transform 0.4s ease,
opacity 0.3s ease;
z-index: 1;
}

.fry-box {
width: 100%;
height: 100%;
position: relative;
transform-style: preserve-3d;
transform: rotateX(-20deg) rotateY(30deg);
}

/* The Red Box Faces */
.box-face {
position: absolute;
border: 2px solid #333;
background: #ff4757;
backface-visibility: visible;
}
.box-face.front {
width: 30px;
height: 35px;
transform: translateZ(15px);
left: 5px;
top: 5px;
}
.box-face.back {
width: 30px;
height: 35px;
transform: rotateY(180deg) translateZ(15px);
left: 5px;
top: 5px;
}
.box-face.right {
width: 30px;
height: 35px;
transform: rotateY(90deg) translateZ(15px);
left: 5px;
top: 5px;
}
.box-face.left {
width: 30px;
height: 35px;
transform: rotateY(-90deg) translateZ(15px);
left: 5px;
top: 5px;
}
.box-face.bottom {
width: 30px;
height: 30px;
transform: rotateX(-90deg) translateZ(30px);
left: 5px;
}

/* The Yellow Fries sticking out */
.fry {
position: absolute;
width: 6px;
height: 25px;
background: #ffd32a;
border: 2px solid #333;
top: -10px;
transform-origin: bottom;
border-radius: 2px;
}

/* Positioning all the fries (Scatter them in 3D) */
/* Front Left */
.fry.f1 {
left: 8px;
transform: translateZ(10px) rotateZ(-10deg);
}
/* Center Tall */
.fry.f2 {
left: 16px;
transform: translateZ(5px) rotateZ(0deg);
height: 32px;
top: -17px;
}
/* Back Center */
.fry.f3 {
left: 12px;
transform: translateZ(-5px) rotateZ(8deg);
}
/* Front Right */
.fry.f4 {
left: 22px;
transform: translateZ(10px) rotateZ(10deg);
height: 20px;
}
/* Back Left */
.fry.f5 {
left: 8px;
transform: translateZ(-8px) rotateZ(-15deg);
height: 28px;
top: -12px;
}
/* Middle Right */
.fry.f6 {
left: 24px;
transform: translateZ(0px) rotateZ(5deg);
height: 24px;
}
/* Middle Center */
.fry.f7 {
left: 14px;
transform: translateZ(12px) rotateZ(-5deg);
height: 26px;
top: -8px;
}

/* ===========================
ANIMATIONS
=========================== */

.switch-input:checked ~ .switch-track .switch-knob {
transform: translateX(
calc(var(--w) - var(--knob-size) - (var(--offset) * 2))
);
transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.switch-input:checked ~ .switch-track .burger-container {
opacity: 0;
transform: scale(0) rotate(-90deg);
}

.switch-input:checked ~ .switch-track .fries-container {
opacity: 1;
transform: scale(1);
}

.switch-input:checked ~ .switch-track .fry-box {
animation: spinFries 3s infinite linear;
}

.switch-input:checked ~ .switch-track {
background-color: var(--bg-fries);
}

@keyframes spinFries {
0% {
transform: rotateX(-20deg) rotateY(0deg);
}
100% {
transform: rotateX(-20deg) rotateY(360deg);
}

.flip-switch-container {
--card-width: 110px;
--card-height: 120px;
--switch-bg: rgba(255, 255, 255, 0.1);
--switch-border-color: rgba(255, 255, 255, 0.2);
--text-color: #ffffff;
--inactive-text-color: rgba(255, 255, 255, 0.6);
--icon-shadow-color: rgba(0, 0, 0, 0.3);
--card-bg: linear-gradient(
135deg,
rgba(255, 255, 255, 0.2),
rgba(255, 255, 255, 0.1)
);
--highlight-color: #64ffda;

display: grid;
place-content: center;
min-height: 100%;
font-family: "Poppins", sans-serif;
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;
}

.flip-switch {
display: flex;
position: relative;
width: calc(var(--card-width) * 2);
height: var(--card-height);
background: var(--switch-bg);
border-radius: 20px;
border: 1px solid var(--switch-border-color);
box-shadow:
0 8px 32px 0 rgba(31, 38, 135, 0.37),
inset 0 4px 8px rgba(255, 255, 255, 0.1);
backdrop-filter: blur(12px);
-webkit-backdrop-filter: blur(12px);
perspective: 1000px;
}

.flip-switch input[type="radio"] {
display: none;
}

.flip-switch .switch-button {
flex: 1;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
gap: 8px;
cursor: pointer;
z-index: 2;
color: var(--inactive-text-color);
transition: all 0.3s ease;
-webkit-tap-highlight-color: transparent;
position: relative;
}

.flip-switch .switch-button:hover {
color: var(--text-color);
}

.flip-switch .switch-button:hover svg {
transform: translateY(-3px);
filter: drop-shadow(0 4px 6px var(--icon-shadow-color)) brightness(1.2);
}

.flip-switch .switch-button svg {
transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
filter: drop-shadow(0 2px 3px var(--icon-shadow-color));
width: 24px;
height: 24px;
}

.flip-switch .switch-button span {
font-size: 14px;
font-weight: 500;
letter-spacing: 0.5px;
}

.flip-switch #switch-opt-1:checked ~ [for="switch-opt-1"],
.flip-switch #switch-opt-2:checked ~ [for="switch-opt-2"] {
color: var(--text-color);
text-shadow: 0 0 8px rgba(100, 255, 218, 0.5);
}

.flip-switch #switch-opt-1:checked ~ [for="switch-opt-2"],
.flip-switch #switch-opt-2:checked ~ [for="switch-opt-1"] {
color: var(--inactive-text-color);
}

.flip-switch .switch-card {
position: absolute;
top: 0;
left: 0;
width: var(--card-width);
height: var(--card-height);
z-index: 1;
transform-style: preserve-3d;
}

.flip-switch .card-face {
position: absolute;
width: 100%;
height: 100%;
border-radius: 20px;
background: var(--card-bg);
border: 1px solid rgba(255, 255, 255, 0.15);
box-shadow:
0 4px 20px rgba(0, 0, 0, 0.2),
inset 0 2px 4px rgba(255, 255, 255, 0.1);
backface-visibility: hidden;
-webkit-backface-visibility: hidden;
}

.flip-switch .card-back {
transform: rotateY(180deg);
}

.flip-switch #switch-opt-2:checked ~ .switch-card {
animation: flipRight 0.6s cubic-bezier(0.76, 0, 0.24, 1) forwards;
}

.flip-switch #switch-opt-1:checked ~ .switch-card {
animation: flipLeft 0.6s cubic-bezier(0.76, 0, 0.24, 1) forwards;
}

@keyframes flipRight {
0% {
transform: translateX(0%) rotateY(0deg);
}
50% {
transform: translateX(50%) rotateY(90deg) scale(1.05);
}
100% {
transform: translateX(100%) rotateY(180deg) scale(1);
}
}

@keyframes flipLeft {
0% {
transform: translateX(100%) rotateY(180deg);
}
50% {
transform: translateX(50%) rotateY(90deg) scale(1.05);
}
100% {
transform: translateX(0%) rotateY(0deg) scale(1);
}
}

.flip-switch #switch-opt-1:checked ~ [for="switch-opt-1"]::after,
.flip-switch #switch-opt-2:checked ~ [for="switch-opt-2"]::after {
content: "";
position: absolute;
bottom: -5px;
width: 30px;
height: 3px;
background: var(--highlight-color);
border-radius: 2px;
animation: glow 1.5s infinite alternate;
}

@keyframes glow {
from {
box-shadow: 0 0 5px var(--highlight-color);
}
to {
box-shadow:
0 0 15px var(--highlight-color),
0 0 25px var(--highlight-color);
}
